// =====================================================
// موتور نامه‌ها - صبا تجهیز لاله پارسه
// نسخه چندصفحه‌ای
// =====================================================
//
// امکانات:
// - شماره‌گذاری خودکار نامه
// - تاریخ شمسی
// - نامه داخلی و خارجی
// - امضای نامه
// - QR برای نامه خارجی
// - PDF چندصفحه‌ای
// - فاصله پایین صفحه 35mm
// - امضا در تمام صفحات
// - QR در تمام صفحات نامه خارجی
// - جلوگیری از افتادن امضا یا QR از صفحه
// =====================================================


// =====================================================
// ذخیره / بارگذاری نامه‌ها — stlpLoadLetters/stlpSaveLetters اینجا
// عمداً تعریف نشده‌اند؛ app.js (که قبل از این فایل لود می‌شود) همین
// دو تابع را دارد. یک نسخه‌ی دوم و یکسانِ همین‌ها قبلاً همین‌جا هم
// بود که چون بعد از app.js لود می‌شد، همیشه همان یکی «برنده» می‌شد —
// بی‌خطر بود چون دقیقاً یکسان بودند، ولی یک تله‌ی خاموش برای آینده
// بود (اگر یکی از دو نسخه بعداً تغییر می‌کرد، آن تغییر همیشه بی‌اثر
// می‌ماند بدون هیچ خطایی).
// =====================================================


// =====================================================
// شماره‌گذاری خودکار نامه
// =====================================================

function stlpGetNextLetterNumberLocal() {

    const letters = stlpLoadLetters();

    if (letters.length === 0) {
        return 1;
    }

    const numbers =
        letters
            .map(function(l) {
                return Number(l.letterNo) || 0;
            })
            .filter(function(n) {
                return n > 0;
            });

    if (numbers.length === 0) {
        return 1;
    }

    return Math.max.apply(null, numbers) + 1;

}


// اتمیک از سرور می‌گیرد تا دو ثبتِ هم‌زمانِ نامه شماره‌ی تکراری نگیرند؛
// اگر سرور در دسترس نبود، به محاسبه‌ی محلیِ قدیمی (max+۱) برمی‌گردد.
function stlpGetNextLetterNumber() {

    if (typeof stlpNextCounterFromServerSync === "function") {
        return stlpNextCounterFromServerSync(
            "/api/counter/next-letter-number",
            stlpGetNextLetterNumberLocal
        );
    }

    return stlpGetNextLetterNumberLocal();

}


// =====================================================
// تاریخ شمسی امروز
// =====================================================

function stlpLetterTodayFa() {

    try {

        const formatter =
            new Intl.DateTimeFormat(
                "fa-IR-u-ca-persian",
                {
                    year: "numeric",
                    month: "2-digit",
                    day: "2-digit"
                }
            );

        const parts =
            formatter.formatToParts(new Date());

        const map = {};

        parts.forEach(function(p) {
            map[p.type] = p.value;
        });

        const toEn = function(s) {

            return String(s || "").replace(
                /[۰-۹]/g,
                function(d) {
                    return "۰۱۲۳۴۵۶۷۸۹".indexOf(d);
                }
            );

        };

        return (
            toEn(map.year) +
            "/" +
            toEn(map.month).padStart(2, "0") +
            "/" +
            toEn(map.day).padStart(2, "0")
        );

    } catch (error) {

        return new Date().toLocaleDateString("fa-IR");

    }

}


// =====================================================
// ساخت پیش‌نویس نامه
// =====================================================

function stlpCreateLetterDraft(type) {

    const currentUser =
        typeof stlpCurrentUser === "function"
            ? stlpCurrentUser()
            : null;

    return {

        id:
            "ltr_" +
            Date.now().toString(36) +
            Math.random()
                .toString(36)
                .substring(2, 6),

        letterNo:
            stlpGetNextLetterNumber(),

        date:
            stlpLetterTodayFa(),

        type:
            type,

        subject:
            "",

        body:
            "",

        hasAttachment:
            false,

        recipientUserIds:
            [],

        readBy:
            [],

        recipientName:
            "",

        signerUserId:
            "",

        signerName:
            "",

        signedAt:
            "",

        qrPayload:
            "",

        createdByUserId:
            currentUser ? currentUser.id : "",

        createdByName:
            currentUser
                ? (
                    currentUser.fullName ||
                    currentUser.username
                )
                : "",

        createdAt:
            new Date().toISOString()

    };

}


// =====================================================
// بررسی مجوز امضا
// =====================================================

function stlpUserCanSignLetters(user) {

    if (!user) {
        return false;
    }

    return !!(
        user.isAdmin ||
        user.canSignLetters
    );

}


// =====================================================
// امضای نامه داخلی
// =====================================================

function stlpSignInternalLetter(
    letter,
    signerUser
) {

    if (!signerUser) {

        throw new Error(
            "کاربر امضاکننده مشخص نیست."
        );

    }

    letter.signerUserId =
        signerUser.id;

    letter.signerName =
        signerUser.fullName ||
        signerUser.username;

    letter.signedAt =
        new Date().toISOString();

    letter.qrPayload =
        "";

    return letter;

}


// =====================================================
// امضای نامه خارجی
// =====================================================

function stlpSignExternalLetter(
    letter,
    signerUser
) {

    if (!signerUser) {

        throw new Error(
            "کاربر امضاکننده مشخص نیست."
        );

    }

    if (!stlpUserCanSignLetters(signerUser)) {

        throw new Error(
            "فقط مدیرانی که مجوز امضای نامه خارج‌سازمانی دارند می‌توانند این نامه را امضا کنند."
        );

    }

    letter.signerUserId =
        signerUser.id;

    letter.signerName =
        signerUser.fullName ||
        signerUser.username;

    letter.signedAt =
        new Date().toISOString();

    letter.qrPayload =
        "STLP-LETTER|" +
        letter.letterNo +
        "|" +
        letter.date +
        "|" +
        letter.signerName;

    return letter;

}


// =====================================================
// خوانده‌شدن نامه
// =====================================================

function stlpMarkLetterRead(
    letter,
    userId
) {

    if (!Array.isArray(letter.readBy)) {
        letter.readBy = [];
    }

    const already =
        letter.readBy.some(function(r) {
            return r.userId === userId;
        });

    if (!already) {

        letter.readBy.push({
            userId:
                userId,

            readAt:
                new Date().toISOString()
        });

    }

    return letter;

}


function stlpLetterIsReadBy(
    letter,
    userId
) {

    return (
        Array.isArray(letter.readBy) &&
        letter.readBy.some(function(r) {
            return r.userId === userId;
        })
    );

}


// =====================================================
// QR
// =====================================================

function stlpRenderLetterQr(
    containerEl,
    payload
) {

    if (!containerEl) {
        return;
    }

    containerEl.innerHTML = "";

    if (!payload) {
        return;
    }

    if (typeof QRCode !== "undefined") {

        try {

            new QRCode(
                containerEl,
                {
                    text:
                        payload,

                    width:
                      80,

                    height:
                        80,

                    colorDark:
                        "#000000",

                    colorLight:
                        "#ffffff00",

                    correctLevel:
                        QRCode.CorrectLevel.M
                }
            );

            return;

        } catch (error) {

            console.warn(
                "خطا در ساخت QR:",
                error
            );

        }

    }

    containerEl.innerHTML =
        '<div style="' +
        'border:1px solid #333;' +
        'padding:5px;' +
        'font-size:8px;' +
        'width:68px;' +
        'word-break:break-all;' +
        'text-align:center;' +
        'background:#fff;' +
        '">' +
        stlpLetterEsc(payload) +
        "</div>";

}


// =====================================================
// Base64 لوگو و سربرگ
// =====================================================
//
// اینجا Base64 خودت را قرار بده
//

const STLP_LETTER_LOGO_B64 = "";
;

const STLP_LETTERHEAD_BG_B64 = ""
;


// =====================================================
// Escape
// =====================================================

function stlpLetterEsc(value) {

    return String(
        value == null
            ? ""
            : value
    )
        .replace(
            /&/g,
            "&amp;"
        )
        .replace(
            /</g,
            "&lt;"
        )
        .replace(
            />/g,
            "&gt;"
        );

}


// =====================================================
// ساخت HTML پیش‌نمایش نامه
// =====================================================

function stlpBuildLetterHtml(
    letter,
    recipientLabel
) {

    const bodyParagraphs =
        String(letter.body || "")
            .split("\n")
            .map(function(line) {

                return (
                    "<p style=\"" +
                    "margin:0 0 10px;" +
                    "text-indent:6mm;" +
                    "overflow-wrap:break-word;" +
                    "\">" +
                    stlpLetterEsc(line) +
                    "</p>"
                );

            })
            .join("");

    const attachmentText =
        letter.hasAttachment
            ? "دارد"
            : "ندارد";

    const qrBlockId =
        "letterQr_" +
        letter.id;

    const isExternal =
        letter.type === "external";

    return `

        <div
            class="stlp-letter-page"
            style="
                background-image:url(
                    data:image/png;base64,${STLP_LETTERHEAD_BG_B64}
                );
                background-size:210mm 297mm;
                background-repeat:no-repeat;
            "
        >

            <div class="stlp-letter-meta">

                <div>
                    تاریخ:
                    <b>${stlpLetterEsc(letter.date)}</b>
                </div>

                <div>
                    شماره:
                    <b>${stlpLetterEsc(letter.letterNo)}</b>
                </div>

                <div>
                    پیوست:
                    <b>${attachmentText}</b>
                </div>

            </div>


            <div class="stlp-letter-body">

                <div class="stlp-letter-recipient">

                    <b>گیرنده:</b>
                    ${stlpLetterEsc(
                        recipientLabel || ""
                    )}

                </div>


                ${
                    letter.subject
                        ? (
                            '<div class="stlp-letter-subject">' +
                            '<b>موضوع:</b> ' +
                            stlpLetterEsc(
                                letter.subject
                            ) +
                            '</div>'
                        )
                        : ""
                }


                <div class="stlp-letter-text">

                    ${bodyParagraphs}

                </div>


                <div
                    class="stlp-letter-signature"
                    style="
                        page-break-inside:avoid;
                        break-inside:avoid;
                    "
                >

                    <div
                        class="stlp-letter-signature-label"
                    >
                        ${
                            isExternal
                                ? "امضای مدیر"
                                : "امضا"
                        }
                    </div>

                    <div
                        class="stlp-letter-signature-name"
                    >
                        ${stlpLetterEsc(
                            letter.signerName || "—"
                        )}
                    </div>


                    ${
                        isExternal &&
                        letter.qrPayload
                            ? (
                                '<div id="' +
                                qrBlockId +
                                '" ' +
                                'class="stlp-letter-qr"></div>'
                            )
                            : ""
                    }

                </div>

            </div>

        </div>

    `;

}


// =====================================================
// نصب QR در پیش‌نمایش
// =====================================================

function stlpMountLetterQr(letter) {

    if (
        letter.type !== "external" ||
        !letter.qrPayload
    ) {
        return;
    }

    const el =
        document.getElementById(
            "letterQr_" +
            letter.id
        );

    if (el) {

        stlpRenderLetterQr(
            el,
            letter.qrPayload
        );

    }

}


// =====================================================
// دانلود PDF
// =====================================================
//
// تنظیمات اصلی:
//
// A4 = 297mm
//
// شروع متن = 45mm
//
// فاصله پایین صفحه = 35mm
//
// فضای امضا = حدود 30mm
//
// بنابراین متن قبل از امضا محدود می‌شود.
//
// امضا در تمام صفحات قرار می‌گیرد.
// QR نیز در تمام صفحات نامه خارجی قرار می‌گیرد.
// =====================================================

async function stlpDownloadLetterPdf(
    letter,
    recipientLabel
) {

    if (
        typeof html2canvas === "undefined" ||
        typeof window.jspdf === "undefined"
    ) {

        alert(
            "❌ کتابخانه‌های ساخت PDF هنوز لود نشده‌اند."
        );

        return;

    }


    // =================================================
    // تنظیمات صفحه
    // =================================================

    const PAGE_WIDTH_MM = 210;

    const PAGE_HEIGHT_MM = 297;

    const CONTENT_TOP_MM = 45;

    // فاصله دقیق از پایین صفحه
    const RESERVED_BOTTOM_MM = 35;

    // فضای رزرو برای امضا
    const SIGNATURE_SPACE_MM = 30;

    // فاصله امن اضافی
    const SAFETY_SPACE_MM = 5;


    // ارتفاع قابل استفاده کل
    const CONTENT_HEIGHT_MM =
        PAGE_HEIGHT_MM -
        CONTENT_TOP_MM -
        RESERVED_BOTTOM_MM;


    // ارتفاع متن
    const TEXT_MAX_HEIGHT_MM =
        CONTENT_HEIGHT_MM -
        SIGNATURE_SPACE_MM -
        SAFETY_SPACE_MM;


    const renderRoot =
        document.createElement("div");

    renderRoot.style.position =
        "fixed";

    renderRoot.style.left =
        "-100000px";

    renderRoot.style.top =
        "0";

    renderRoot.style.width =
        "210mm";

    renderRoot.style.background =
        "#fff";

    renderRoot.style.zIndex =
        "-9999";

    document.body.appendChild(
        renderRoot
    );


    try {

        // =============================================
        // تبدیل متن به پاراگراف
        // =============================================

        const rawLines =
            String(letter.body || "")
                .replace(
                    /\r\n/g,
                    "\n"
                )
                .replace(
                    /\r/g,
                    "\n"
                )
                .split("\n");


        const paragraphs =
            rawLines.map(
                function(line) {
                    return line.trim();
                }
            );


        // =============================================
        // صفحه اندازه‌گیری
        // =============================================

        const measurePage =
            document.createElement("div");

        measurePage.className =
            "stlp-letter-page";

        measurePage.style.position =
            "relative";

        measurePage.style.width =
            "210mm";

        measurePage.style.height =
            "297mm";

        measurePage.style.minHeight =
            "297mm";

        measurePage.style.backgroundColor =
            "#fff";

        measurePage.style.backgroundImage =
            "url(data:image/png;base64," +
            STLP_LETTERHEAD_BG_B64 +
            ")";

        measurePage.style.backgroundSize =
            "210mm 297mm";

        measurePage.style.backgroundRepeat =
            "no-repeat";

        measurePage.style.boxSizing =
            "border-box";

        renderRoot.appendChild(
            measurePage
        );


        // =============================================
        // بدنه اندازه‌گیری
        // =============================================

        const measureBody =
            document.createElement("div");

        measureBody.className =
            "stlp-letter-body";

        measureBody.style.position =
            "absolute";

        measureBody.style.top =
            CONTENT_TOP_MM + "mm";

        measureBody.style.right =
            "15mm";

        measureBody.style.left =
            "15mm";

        measureBody.style.bottom =
            RESERVED_BOTTOM_MM + "mm";

        measureBody.style.height =
            CONTENT_HEIGHT_MM + "mm";

        measureBody.style.boxSizing =
            "border-box";

        measureBody.style.overflow =
            "hidden";

        measurePage.appendChild(
            measureBody
        );


        // =============================================
        // گیرنده
        // =============================================

        const recipientEl =
            document.createElement("div");

        recipientEl.className =
            "stlp-letter-recipient";

        recipientEl.innerHTML =
            "<b>گیرنده:</b> " +
            stlpLetterEsc(
                recipientLabel || ""
            );

        measureBody.appendChild(
            recipientEl
        );


        // =============================================
        // موضوع
        // =============================================

        if (letter.subject) {

            const subjectEl =
                document.createElement("div");

            subjectEl.className =
                "stlp-letter-subject";

            subjectEl.innerHTML =
                "<b>موضوع:</b> " +
                stlpLetterEsc(
                    letter.subject
                );

            measureBody.appendChild(
                subjectEl
            );

        }


        // =============================================
        // متن
        // =============================================

        const textEl =
            document.createElement("div");

        textEl.className =
            "stlp-letter-text";

        measureBody.appendChild(
            textEl
        );


        // =============================================
        // اندازه‌گیری ارتفاع واقعی
        // =============================================

        function testLines(lines) {

            textEl.innerHTML =
                lines
                    .map(function(line) {

                        return (
                            "<p style=\"" +
                            "margin:0 0 10px;" +
                            "text-indent:6mm;" +
                            "overflow-wrap:break-word;" +
                            "word-break:normal;" +
                            "\">" +
                            stlpLetterEsc(
                                line || " "
                            ) +
                            "</p>"
                        );

                    })
                    .join("");


            return (
                textEl.scrollHeight <=
                (
                    TEXT_MAX_HEIGHT_MM *
                    3.779527559
                )
            );

        }


        // =============================================
        // تقسیم صفحات
        // =============================================

        const pages = [];

        let currentPageLines = [];


        paragraphs.forEach(
            function(line) {

                const candidate =
                    currentPageLines.concat(
                        [line]
                    );


                if (
                    testLines(candidate)
                ) {

                    currentPageLines =
                        candidate;

                } else {

                    if (
                        currentPageLines.length > 0
                    ) {

                        pages.push(
                            currentPageLines
                        );

                    }


                    currentPageLines =
                        [line];


                    testLines(
                        currentPageLines
                    );

                }

            }
        );


        if (
            currentPageLines.length > 0
        ) {

            pages.push(
                currentPageLines
            );

        }


        if (
            pages.length === 0
        ) {

            pages.push([]);

        }


        // =============================================
        // پاک کردن صفحه اندازه‌گیری
        // =============================================

        renderRoot.innerHTML = "";


        // =============================================
        // ساخت صفحات واقعی
        // =============================================

        pages.forEach(
            function(
                pageLines,
                pageIndex
            ) {

                const page =
                    document.createElement("div");

                page.className =
                    "stlp-letter-page";

                page.style.position =
                    "relative";

                page.style.width =
                    "210mm";

                page.style.height =
                    "297mm";

                page.style.minHeight =
                    "297mm";

                page.style.backgroundColor =
                    "#fff";

                page.style.backgroundImage =
                    "url(data:image/png;base64," +
                    STLP_LETTERHEAD_BG_B64 +
                    ")";

                page.style.backgroundSize =
                    "210mm 297mm";

                page.style.backgroundRepeat =
                    "no-repeat";

                page.style.boxSizing =
                    "border-box";


                // =====================================
                // متادیتا
                // =====================================

                const meta =
                    document.createElement("div");

                meta.className =
                    "stlp-letter-meta";

                meta.innerHTML =

                    "<div>" +
                    "تاریخ: <b>" +
                    stlpLetterEsc(
                        letter.date
                    ) +
                    "</b>" +
                    "</div>" +

                    "<div>" +
                    "شماره: <b>" +
                    stlpLetterEsc(
                        letter.letterNo
                    ) +
                    "</b>" +
                    "</div>" +

                    "<div>" +
                    "پیوست: <b>" +
                    (
                        letter.hasAttachment
                            ? "دارد"
                            : "ندارد"
                    ) +
                    "</b>" +
                    "</div>";


                page.appendChild(
                    meta
                );


                // =====================================
                // بدنه
                // =====================================

                const body =
                    document.createElement("div");

                body.className =
                    "stlp-letter-body";

                body.style.position =
                    "absolute";

                body.style.top =
                    CONTENT_TOP_MM + "mm";

                body.style.right =
                    "15mm";

                body.style.left =
                    "15mm";

                body.style.bottom =
                    RESERVED_BOTTOM_MM + "mm";

                body.style.height =
                    CONTENT_HEIGHT_MM + "mm";

                body.style.boxSizing =
                    "border-box";

                body.style.overflow =
                    "hidden";


                // =====================================
                // گیرنده فقط صفحه اول
                // =====================================

                if (pageIndex === 0) {

                    const recipient =
                        document.createElement(
                            "div"
                        );

                    recipient.className =
                        "stlp-letter-recipient";

                    recipient.innerHTML =
                        "<b>گیرنده:</b> " +
                        stlpLetterEsc(
                            recipientLabel || ""
                        );

                    body.appendChild(
                        recipient
                    );


                    if (letter.subject) {

                        const subject =
                            document.createElement(
                                "div"
                            );

                        subject.className =
                            "stlp-letter-subject";

                        subject.innerHTML =
                            "<b>موضوع:</b> " +
                            stlpLetterEsc(
                                letter.subject
                            );

                        body.appendChild(
                            subject
                        );

                    }

                } else {

                    // =================================
                    // عنوان صفحات ادامه
                    // =================================

                    const continuation =
                        document.createElement(
                            "div"
                        );

                    continuation.style.fontSize =
                        "11px";

                    continuation.style.color =
                        "#666";

                    continuation.style.marginBottom =
                        "8px";

                    continuation.style.fontWeight =
                        "700";

                    continuation.innerHTML =
                        "ادامه نامه شماره " +
                        stlpLetterEsc(
                            letter.letterNo
                        );

                    body.appendChild(
                        continuation
                    );

                }


                // =====================================
                // متن صفحه
                // =====================================

                const text =
                    document.createElement(
                        "div"
                    );

                text.className =
                    "stlp-letter-text";

                text.innerHTML =
                    pageLines
                        .map(
                            function(line) {

                                return (
                                    "<p style=\"" +
                                    "margin:0 0 10px;" +
                                    "text-indent:6mm;" +
                                    "overflow-wrap:break-word;" +
                                    "word-break:normal;" +
                                    "\">" +
                                    stlpLetterEsc(
                                        line || " "
                                    ) +
                                    "</p>"
                                );

                            }
                        )
                        .join("");


                body.appendChild(
                    text
                );


                // =====================================
                // امضا در تمام صفحات
                // =====================================

                const signature =
                    document.createElement(
                        "div"
                    );

                signature.className =
                    "stlp-letter-signature";

                signature.style.position =
                    "absolute";

                signature.style.bottom =
                    "3mm";

                signature.style.left =
                    "0";

                signature.style.right =
                    "0";

                signature.style.height =
                    "27mm";

                signature.style.margin =
                    "0";

                signature.style.textAlign =
                    "left";

                signature.style.paddingLeft =
                    "10mm";

                signature.style.boxSizing =
                    "border-box";

                signature.style.pageBreakInside =
                    "avoid";

                signature.style.breakInside =
                    "avoid";


                // =====================================
                // عنوان امضا
                // =====================================

                const signatureLabel =
                    document.createElement(
                        "div"
                    );

                signatureLabel.className =
                    "stlp-letter-signature-label";

                signatureLabel.style.fontSize =
                    "12px";

                signatureLabel.style.fontWeight =
                    "700";

                signatureLabel.style.marginBottom =
                    "4px";

                signatureLabel.innerText =
                    letter.type === "external"
                        ? "امضای مدیر"
                        : "امضا";


                signature.appendChild(
                    signatureLabel
                );


                // =====================================
                // نام امضاکننده
                // =====================================

                const signatureName =
                    document.createElement(
                        "div"
                    );

                signatureName.className =
                    "stlp-letter-signature-name";

                signatureName.style.fontSize =
                    "13px";

                signatureName.style.fontWeight =
                    "700";

                signatureName.innerText =
                    letter.signerName ||
                    "—";


                signature.appendChild(
                    signatureName
                );


                // =====================================
                // QR در تمام صفحات خارجی
                // =====================================

                if (
                    letter.type === "external" &&
                    letter.qrPayload
                ) {

                    const qr =
                        document.createElement(
                            "div"
                        );

                    qr.id =
                        "letterQrPdf_" +
                        letter.id +
                        "_" +
                        pageIndex;

                    qr.className =
                        "stlp-letter-qr";

                    qr.style.marginTop =
                        "3px";

                    // QR را ۱ سانتی‌متر به بالا منتقل می‌کنیم
                    qr.style.transform =
                        "translateY(-10mm)";

                    qr.style.width =
                        "75px";

                    qr.style.height =
                        "75px";

                    qr.style.display =
                        "block";

                    signature.appendChild(
                        qr
                    );

                }


                body.appendChild(
                    signature
                );


                page.appendChild(
                    body
                );


                renderRoot.appendChild(
                    page
                );

            }
        );


        // =============================================
        // صبر برای رندر DOM
        // =============================================

        await new Promise(
            function(resolve) {

                setTimeout(
                    resolve,
                    500
                );

            }
        );


        // =============================================
        // ساخت QR در تمام صفحات
        // =============================================

        if (
            letter.type === "external" &&
            letter.qrPayload
        ) {

            pages.forEach(
                function(_, pageIndex) {

                    const qr =
                        document.getElementById(
                            "letterQrPdf_" +
                            letter.id +
                            "_" +
                            pageIndex
                        );

                    if (qr) {

                        stlpRenderLetterQr(
                            qr,
                            letter.qrPayload
                        );

                    }

                }
            );

        }


        // =============================================
        // صبر دوباره برای QR
        // =============================================

        await new Promise(
            function(resolve) {

                setTimeout(
                    resolve,
                    400
                );

            }
        );


        // =============================================
        // ساخت PDF
        // =============================================

        const { jsPDF } =
            window.jspdf;


        const pdf =
            new jsPDF(
                {
                    orientation:
                        "portrait",

                    unit:
                        "mm",

                    format:
                        "a4",

                    compress:
                        true
                }
            );


        const pageElements =
            Array.from(
                renderRoot.querySelectorAll(
                    ".stlp-letter-page"
                )
            );


        // =============================================
        // تبدیل هر صفحه به PDF
        // =============================================

        for (
            let i = 0;
            i < pageElements.length;
            i++
        ) {

            const pageEl =
                pageElements[i];


            const canvas =
                await html2canvas(
                    pageEl,
                    {
                        scale:
                            2.5,

                        useCORS:
                            true,

                        allowTaint:
                            false,

                        backgroundColor:
                            "#ffffff",

                        logging:
                            false,

                        imageTimeout:
                            15000
                    }
                );


            const imgData =
                canvas.toDataURL(
                    "image/jpeg",
                    0.95
                );


            if (i > 0) {

                pdf.addPage();

            }


            pdf.addImage(
                imgData,
                "JPEG",
                0,
                0,
                210,
                297,
                undefined,
                "FAST"
            );

        }


        // =============================================
        // دانلود
        // =============================================

        pdf.save(
            "نامه-شماره-" +
            letter.letterNo +
            ".pdf"
        );


    } catch (error) {

        console.error(
            "❌ خطا در ساخت PDF نامه:",
            error
        );

        alert(
            "❌ خطا در ساخت PDF نامه:\n" +
            (
                error.message ||
                error
            )
        );


    } finally {

        if (
            renderRoot.parentNode
        ) {

            renderRoot.parentNode.removeChild(
                renderRoot
            );

        }

    }

}


// =====================================================
// چاپ مستقیم مرورگر
// =====================================================

function stlpPrintLetter(
    letter,
    recipientLabel
) {

    const printArea =
        document.getElementById(
            "letterPrintArea"
        );


    if (!printArea) {

        alert(
            "❌ ناحیه چاپ در این صفحه پیدا نشد."
        );

        return;

    }


    printArea.innerHTML =
        stlpBuildLetterHtml(
            letter,
            recipientLabel
        );


    stlpMountLetterQr(
        letter
    );


    printArea.style.display =
        "block";


    const afterPrint =
        function() {

            printArea.style.display =
                "none";

            window.removeEventListener(
                "afterprint",
                afterPrint
            );

        };


    window.addEventListener(
        "afterprint",
        afterPrint
    );


    setTimeout(
        function() {

            window.print();

        },
        150
    );

}
